        ..enqueueToolCall('bash', '{"command": "true"}')
        ..enqueueToolCall('bash', '{"command": "true"}')
        ..enqueueToolCall('bash', '{"command": "true"}')
        ..enqueueToolCall('bash', '{"command": "true"}')
        ..enqueueText('seeds done')
